        public static void BuildWorld(Transform player,int crowdPerDistrict){BuildUrbanDistrict("Shinjuku 1989",Vector3.zero,player,true);BuildUrbanDistrict("Shibuya 1992",new Vector3(150,0,0),player,false);BuildCountryside(new Vector3(0,0,150),player);CrowdSpawnerV2.SpawnJapaneseCrowd(Vector3.zero,crowdPerDistrict,31f);CrowdSpawnerV2.SpawnJapaneseCrowd(new Vector3(150,0,0),Mathf.Max(14,crowdPerDistrict-8),29f);CrowdSpawnerV2.SpawnJapaneseCrowd(new Vector3(0,0,150),Mathf.Max(7,crowdPerDistrict/4),18f);}
