            var karaoke=Block("Karaoke Melody",o+new Vector3(19,1.5f,18),new Vector3(6,3,5),new Color(.38f,.08f,.34f));karaoke.AddComponent<KaraokeBooth>();Neon(karaoke.transform,new Color(.95f,.20f,.72f));
