        static void BuildBlockRow(Vector3 start,int facing){for(int i=0;i<4;i++){float z=i*8f;float h=Random.Range(7f,15f);var b=Block("Era Building",start+new Vector3(0,h/2,z),new Vector3(Random.Range(8f,11f),h,7),new Color(Random.Range(.20f,.34f),Random.Range(.20f,.32f),Random.Range(.18f,.28f)));for(int floor=1;floor<Mathf.FloorToInt(h/2.6f);floor++)for(int x=-2;x<=2;x+=2)Block("Window",b.transform.position+new Vector3(facing*(b.transform.localScale.x/2+.03f),-h/2+1.7f+floor*2.4f,x),new Vector3(.05f,1.0f,1.15f),new Color(.58f,.55f,.42f));if(i%2==0)Neon(b.transform,Random.value>.5f?new Color(.75f,.10f,.12f):new Color(.08f,.42f,.63f));}}
